// Violates ISP: fat interface forces all implementors to handle all methods
interface UserRepository {
    User findById(Long id);
    void save(User user);
    void delete(Long id);
    List<User> exportToCsv();  // Not all clients need this
}

// ReadOnlyUserService is forced to implement methods it never uses
class ReadOnlyUserService implements UserRepository {
    public User findById(Long id) { return /* actual logic */ null; }
    public void save(User user) { throw new UnsupportedOperationException(); }
    public void delete(Long id) { throw new UnsupportedOperationException(); }
    public List<User> exportToCsv() { throw new UnsupportedOperationException(); }
}

// ISP-compliant: split into focused interfaces
interface UserReader {
    User findById(Long id);
}

interface UserWriter {
    void save(User user);
    void delete(Long id);
}

// Now ReadOnlyUserService only implements what it needs
class ReadOnlyUserService implements UserReader {
    public User findById(Long id) { return /* actual logic */ null; }  // Clean, no fake methods
}

// Fat interface: mixes read, write, import, export, and admin operations
interface ProductService {
    Product findById(Long id);
    List<Product> findAll();
    void save(Product product);
    void delete(Long id);
    void bulkImport(List<Product> products);
    byte[] exportToPdf();
    void archiveOldProducts();
    void recalculatePrices();
}

// A simple product display service is forced to implement everything
@Service
class ProductDisplayService implements ProductService {
    public Product findById(Long id) { /* real logic */ return null; }
    public List<Product> findAll() { /* real logic */ return List.of(); }

    // These methods are never called but must exist
    public void save(Product product) { throw new UnsupportedOperationException("Read-only service"); }
    public void delete(Long id) { throw new UnsupportedOperationException(); }
    public void bulkImport(List<Product> products) { throw new UnsupportedOperationException(); }
    public byte[] exportToPdf() { throw new UnsupportedOperationException(); }
    public void archiveOldProducts() { throw new UnsupportedOperationException(); }
    public void recalculatePrices() { throw new UnsupportedOperationException(); }  // Seven wasted methods
}

// Fat interface: all 3 services must change when we add exportToExcel
interface OrderService {
    Order findById(Long id);
    void save(Order order);
    void delete(Long id);
    // New requirement: add exportToExcel — now ALL implementors must change
}

class OrderDisplayService implements OrderService { /* must add exportToExcel */ }
class OrderAdminService implements OrderService { /* must add exportToExcel */ }
class OrderReportService implements OrderService { /* must add exportToExcel */ }

// ISP-compliant: only OrderExporter implementors change
interface OrderReader {
    Order findById(Long id);
}

interface OrderWriter {
    void save(Order order);
    void delete(Long id);
}

interface OrderExporter {
    byte[] exportToPdf();
    // New requirement: add exportToExcel — only classes that export are affected
}

class OrderDisplayService implements OrderReader { /* unchanged */ }
class OrderAdminService implements OrderReader, OrderWriter { /* unchanged */ }
class OrderReportService implements OrderReader, OrderExporter { /* adds exportToExcel here */ }

// ISP in repositories: choose the interface level you need
import org.springframework.data.repository.CrudRepository;
import org.springframework.data.jpa.repository.JpaRepository;

// Simple CRUD — use CrudRepository (5 methods)
interface ProductRepository extends CrudRepository<Product, Long> {
    // Inherits: save, findById, findAll, deleteById, count
}

// Need batching and flushing — use JpaRepository (30+ methods)
interface OrderRepository extends JpaRepository<Order, Long> {
    // Inherits: saveAll, flush, saveAndFlush, deleteInBatch, etc.
}

// ISP in service layer: split by capability
interface UserReader {
    Optional<User> findById(Long id);
    List<User> findAll();
}

interface UserWriter {
    User save(User user);
    void deleteById(Long id);
}

@RestController
class UserProfileController {
    private final UserReader userReader;  // Only depends on read methods

    UserProfileController(UserReader userReader) {
        this.userReader = userReader;
    }

    @GetMapping("/users/{id}")
    User getProfile(@PathVariable Long id) {
        return userReader.findById(id).orElseThrow();
    }
}
